package com.example.batterylow; import android.content.BroadcastReceiver; import android.content.Context; import android.content.Intent; import android.os.BatteryManager; import android.widget.Toast; public class BatteryReceiver extends BroadcastReceiver { @Override public void onReceive(Context c,Intent i){if(Intent.ACTION_BATTERY_LOW.equals(i.getAction()))Toast.makeText(c,"Battery Low Broadcast Received!",Toast.LENGTH_LONG).show();if(Intent.ACTION_BATTERY_CHANGED.equals(i.getAction())){int l=i.getIntExtra(BatteryManager.EXTRA_LEVEL,-1),s=i.getIntExtra(BatteryManager.EXTRA_SCALE,-1);int p=(int)((l*100f)/s);if(p<=15)Toast.makeText(c,"Battery Low! ("+p+"%)",Toast.LENGTH_LONG).show();}}}
